INSERT INTO the_full_order.tb_ingredient_master(ingredient_id,ingredient_name_raw,ingredient_name_std,category_name,base_unit,storage_type,user_id)
SELECT ingredient_id,COALESCE(ingredient_name_raw,ingredient_name_std),COALESCE(ingredient_name_std,ingredient_name_raw),category_name,base_unit,storage_type,#{user_id}
  FROM the_full_order.tb_account_ingredient_master WHERE account_id=#{account_id} AND ingredient_id=#{ingredient_id}
